        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
