{"path":"creative_intent.json","content":"{
  "user_need": "双男主，双向暗恋，玄幻题材，HE。过程要够虐，虐点主要来自外界，可以是其他人物，也可以是家族背景等设定，两人之间的故事可有小误会但不可以有大的矛盾点。10万字篇幅。故事要精彩，不能只写2人的事。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["暗恋", "相爱", "对立", "挣扎", "守护"],
    "scene_elements": ["玄幻世界", "宗门", "正邪对立", "修真", "家族"],
    "relationship_tension": ["正邪对立", "宗门世仇", "身份冲突", "外界压力", "双向暗恋"],
    "user_preferences": {
      "desired_emotion": "虐心但HE",
      "forbidden": ["两人之间的大矛盾", "只写二人世界"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "E28",
    "x_axis_mode_name": "爱上仇人",
    "y_axis_tags": ["双向暗恋", "仙侠修真"],
    "reaction_strength": "↘",
    "tension_stars": 4,
    "forbidden_elements": ["两人之间的大矛盾", "只写二人世界", "BE结局"],
    "x_axis_display": "正道宗门天才与魔教少主分属敌对阵营，宗门世仇与正邪对立成为两人相爱的最大障碍",
    "y_axis_combination_effect": "双向暗恋增加情感张力，仙侠修真提供丰富的世界观和冲突来源",
    "reaction_formula": "E28(爱上仇人) × 双向暗恋 × 仙侠修真 = 正邪对立下的虐心暗恋，外界压力层层加码，最终冲破阻碍HE",
    "platform_fit": ["晋江文学城", "长佩文学", "番茄小说"]
  },
  "one_sentence_synopsis": "正道天才与魔教少主暗中相恋，宗门世仇与身份对立让两人陷入爱恨交织的困境。"
}"}

